import{_ as a,a0 as r,w as i,s as p,ao as l,I as u,x as n,a1 as o,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"Ubuntu 的開發者準備開發一個僅基於 Unity 8的新風格 | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu 的開發者準備開發一個僅基於 Unity 8的新風格 | LCTT (201405) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu 的開發者準備開發一個僅基於 Unity 8的新風格 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu 的開發者準備開發一個僅基於 Unity 8的新風格 | LCTT (201405) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201405/Ubuntu Developers Propose a New Flavor Based Only on Unity 8","title":"Ubuntu 的開發者準備開發一個僅基於 Unity 8的新風格","tag":"201405","desc":""},"relativePath":"201405/Ubuntu Developers Propose a New Flavor Based Only on Unity 8.md","filePath":"[post].md"}'),U={name:"201405/Ubuntu Developers Propose a New Flavor Based Only on Unity 8.md"};function d(y,t,b,m,T,f){const e=r("Link");return i(),p("div",null,[t[11]||(t[11]=l('<h1 id="ubuntu-的開發者準備開發一個僅基於-unity-8的新風格" tabindex="-1">Ubuntu 的開發者準備開發一個僅基於 Unity 8的新風格 <a class="header-anchor" href="#ubuntu-的開發者準備開發一個僅基於-unity-8的新風格" aria-label="Permalink to “Ubuntu 的開發者準備開發一個僅基於 Unity 8的新風格”">​</a></h1><p><img src="http://i1-news.softpedia-static.com/images/news2/Ubuntu-Developers-Propose-a-New-Flavor-Based-Only-on-Unity-8-442262-2.jpg" alt="Current Unity 7 desktop in Ubuntu 14.04 LTS"></p><p><strong>Ubuntu 的開發者提出將開發一個單獨使用 Unity 8的新風格，以幫助他們自由的實驗而不必擔心搞亂操作系統穩定。</strong></p><p>如果你的環境滿足安裝需要的話，現在可以在Ubuntu 14.04 LTS中安裝體驗下 Unity 8 桌面環境的預覽版了。現在，新的桌面還不能在專有驅動下運行，因為它依賴於 Mir，而這玩意兒還沒有獲得 NVIDIA 和 AMD 的官方支持。</p><p>無論如何，有一個新的 Ubuntu 風格對於開發者在新的生態環境中測試他們的創意都會有巨大的幫助，而且從　USB Stick 裏啓動十分方便還能體驗大多數的移植性應用。</p><p>“桌面環境開發組很希望為 Ubuntu 增加一個新的風格（噓~，我們並不是計劃現在就發行一個正式的版本），這個風格將包括為觸屏項目開發的Unity 8桌面和新的應用。最初的意圖是提供一個產品使得開發人員可以在做一個基於該軟件的桌面產品的時候可以估算出所需要的的工作量，並建立一個可以由實驗來找出所需的最佳結合方式的空間。”</p><p>“我們仍將計劃融合當前的桌面環境，但是我們不希望給用户帶來不安穩和造成不便，而且希望並行的發展這個新風格可以使我們真正實現在軟件已經準備就緒的時候再遷移，而不是遷移後再解決用户的原有軟件的兼容問題。” Ubuntu 的開發者 Iain Lane説。</p><p>Ubuntu 14.04 LTS 現在默認使用 Unity 7，而且可能這至少將持續到下一個版本 Ubuntu 14.10。Ubuntu 開發者的目標是最遲在下一個 LTS：Ubuntu 16.04 中讓 Unity 8 和 Mir 成為默認的配置，但是如果事情進展的順利，我們可能會在此之前就能成功。</p><p>這個新風格的名字是什麼還不清楚，但是如果地位確定的話，我們可能在接下來的幾個月就可以得到ISO文件。這將會使得用户更容易地測試 Unity 8 ，而且可以在它成為默認配置之前體驗一把。</p><p>當 Canonical 用 Unity 替換舊的 GNOME 2 的時候，這個轉換引起的震動是如此之大，以至於直到今天在論壇中還時不時的被人提及。有一個專門的 Unity 8 風格可能會緩解這個問題。</p><hr>',11)),u("p",null,[t[1]||(t[1]=n("via: ",-1)),o(e,{href:"http://news.softpedia.com/news/Ubuntu-Developers-Propose-a-New-Flavor-Based-Only-on-Unity-8-442262.shtml"},{default:s(()=>[...t[0]||(t[0]=[n("http://news.softpedia.com/news/Ubuntu-Developers-Propose-a-New-Flavor-Based-Only-on-Unity-8-442262.shtml",-1)])]),_:1})]),u("p",null,[t[4]||(t[4]=n("譯者：",-1)),o(e,{href:"https://github.com/crowner"},{default:s(()=>[...t[2]||(t[2]=[n("crowner",-1)])]),_:1}),t[5]||(t[5]=n(" 校對：",-1)),o(e,{href:"https://github.com/wxy"},{default:s(()=>[...t[3]||(t[3]=[n("wxy",-1)])]),_:1})]),u("p",null,[t[8]||(t[8]=n("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[6]||(t[6]=[n("LCTT",-1)])]),_:1}),t[9]||(t[9]=n(" 原創翻譯，",-1)),o(e,{href:"http://linux.cn/"},{default:s(()=>[...t[7]||(t[7]=[n("Linux中國",-1)])]),_:1}),t[10]||(t[10]=n(" 榮譽推出",-1))])])}const _=a(U,[["render",d]]);export{C as __pageData,_ as default};
